from phase0_v2.conflicts.preprocessing import extract_content
import emoji as _emoji_lib

def _has_emoji_fixed(r: str) -> bool:
    content = extract_content(r, 'emoji_use_vs_avoid')
    if not content:
        return False
    return _emoji_lib.emoji_count(content) > 0

def _no_emoji_fixed(r: str) -> bool:
    content = extract_content(r, 'emoji_use_vs_avoid')
    if not content:
        return True
    return _emoji_lib.emoji_count(content) == 0
